// Workbench auto-iteration MCP bootstrap (issue #8, ADR-0023).
//
// This is a STANDALONE entry point: a CLI (Claude Code, Codex) spawns it as
// its `workbench` stdio MCP server with argv `[<pipeName>, <token>]`, both
// generated by the host at execution time. It connects to the host's named
// pipe, presents the one-shot token, and then pumps MCP stdio frames
// verbatim in both directions. It must never import product code: the CLI
// runtime (plain Node, or the Electron binary under ELECTRON_RUN_AS_NODE)
// only needs to be able to read this one file.
//
// Exit contract: a broken pipe exits non-zero. If the CLI closes our stdin
// first (its own shutdown), we close the socket and exit zero.

import { connect } from "node:net";
import { createInterface } from "node:readline";

const [pipeName, token] = process.argv.slice(2);

if (
  typeof pipeName !== "string" ||
  pipeName.length === 0 ||
  typeof token !== "string" ||
  token.length === 0
) {
  process.stderr.write(
    "workbench mcp bootstrap: usage: auto-iteration-mcp-bootstrap <pipeName> <token>\n",
  );
  process.exit(2);
}

let stdinEnded = false;

const socket = connect(pipeName);

socket.on("error", (error) => {
  process.stderr.write(
    `workbench mcp bootstrap: pipe ${pipeName} failed: ${
      error instanceof Error ? error.message : String(error)
    }\n`,
  );
  process.exit(1);
});

socket.on("close", () => {
  // The host side ended the binding; without it no tool call can ever be
  // served, so exiting quietly would let the CLI mistake a dead workbench
  // server for a healthy one.
  if (stdinEnded) process.exit(0);
  process.exit(1);
});

socket.on("connect", () => {
  socket.write(`${JSON.stringify({ type: "binding-hello", token })}\n`);

  const stdinLines = createInterface({
    input: process.stdin,
    crlfDelay: Infinity,
  });
  stdinLines.on("line", (line) => {
    if (line.trim().length === 0) return;
    socket.write(`${line}\n`);
  });

  const pipeLines = createInterface({ input: socket, crlfDelay: Infinity });
  pipeLines.on("line", (line) => {
    process.stdout.write(`${line}\n`);
  });

  process.stdin.on("end", () => {
    stdinEnded = true;
    socket.end();
  });
  process.stdin.on("error", () => undefined);
});
